export async function addProductToCart(page) {
    await page.getByRole("button", { name: "Add To Cart" }).click();
}

export async function emptyCart(page) {
    await page.getByTestId("empty-cart-btn").click();
}

export async function selectCurrency(page, currencyCode) {
    await page.locator("select[name=\"currency_code\"]").selectOption(currencyCode);
}

export async function fillShippingAddressCity(page, city) {
    await page.locator("#city").fill(city);
}

export async function fillShippingAddressState(page, state) {
    await page.locator("#state").fill(state);
}

export async function fillCheckoutEmail(page, email) {
    await page.locator("#email").fill(email);
}

export async function fillShippingAddressStreet(page, streetAddress) {
    await page.locator("#street_address").fill(streetAddress);
}

export async function placeOrder(page) {
    await page.getByTestId("place-order-btn").click();
}
